import { $state } from 'fict'
export function useObject() { let count = $state(1); return { count, increment: () => count++ } }
export function useArray() { let count = $state(2); return [count, () => count++] }
export function useDirect() { let count = $state(3); return count }

import { useArray, useDirect, useObject } from './hooks'
export function Scenario() {
  const object = useObject()
  const array = useArray()
  const direct = useDirect()
  const values = []
  values.push(object.count, array[0], direct)
  object.increment()
  array[1]()
  values.push(object.count, array[0])
  return values
}

import { createMemo, createSignal } from 'fict/advanced'
export const count = createSignal(2)
export const doubled = createMemo(() => count() * 2)
export function increment() { count(count() + 1) }

import { Hooks } from './barrel'
export function Scenario() {
  const counter = Hooks.useCounter()
  const values = []
  values.push(counter.count)
  counter.increment()
  values.push(counter.count)
  return values
}

import { useWrapped } from './wrapper'
export function Scenario() {
  const wrapped = useWrapped()
  const values = []
  values.push(wrapped.value)
  wrapped.increment()
  values.push(wrapped.value)
  return values
}

import { $state } from 'fict'
function useDirect() { let value = $state(6); return value }
function useObject() { let value = $state(7); return { value } }
function useArray() { let value = $state(8); return [value] }
export { useDirect as "__proto__", useObject as "constructor", useArray as "toString" }

import { "__proto__" as useProto, constructor as useConstructor, toString as useToString } from './hooks'
export function Scenario() {
  const direct = useProto()
  const object = useConstructor()
  const array = useToString()
  return [direct, object.value, array[0]]
}

import { $state } from 'fict'
export type Label = string
export function useCounter() { let count = $state(9); return { count } }

import { useCounter, type Label } from './barrel'
export function Scenario(): Label {
  const counter = useCounter()
  return String(counter.count)
}

import { createMemo, createSignal } from 'fict/advanced'
export const count = createSignal(10)
export const doubled = createMemo(() => count() * 2)
export function increment() { count(count() + 1) }
